package com.ruoyi.framework.audit;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import com.alibaba.fastjson2.JSON;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;
class AuditDeliveryTest{
 private Map<String,Object> event(String id,String time){return Map.of("event_id",id,"event_json",JSON.toJSONString(Map.of("kind","login","event",id,"actor","test","time",time)));}
 private PlatformTransactionManager manager(){var m=mock(PlatformTransactionManager.class);when(m.getTransaction(any())).thenAnswer(a->new SimpleTransactionStatus());return m;}
 @Test void healthyQueueUsesBatchesAndBoundedCycle(){JdbcTemplate j=mock(JdbcTemplate.class);var events=new ArrayList<Map<String,Object>>();for(int i=0;i<100;i++)events.add(event("event-"+i,"2026-10-14T12:00:00"));when(j.queryForList(contains("SKIP LOCKED"))).thenReturn(events);var delivery=new AuditDelivery(j,manager());delivery.deliver();verify(j,times(10)).batchUpdate(contains("INSERT IGNORE INTO sys_logininfor"),anyList());verify(j,times(10)).batchUpdate(contains("delivered_time=NOW()"),anyList());}
 @Test void brokenEventIsRetriedWithoutDiscardingHealthyEvent(){JdbcTemplate j=mock(JdbcTemplate.class);var rows=List.of(event("bad","invalid-time"),event("good","2026-10-14T12:00:00"));when(j.queryForList(contains("SKIP LOCKED"))).thenReturn(rows,List.of());when(j.queryForList(contains("event_id=? FOR UPDATE"),eq("bad"))).thenReturn(List.of(Map.of("status","PENDING","event_json",rows.get(0).get("event_json"))));when(j.queryForList(contains("event_id=? FOR UPDATE"),eq("good"))).thenReturn(List.of(Map.of("status","PENDING","event_json",rows.get(1).get("event_json"))));new AuditDelivery(j,manager()).deliver();verify(j).update(contains("attempts=attempts+1"),eq("bad"));verify(j).update(contains("delivered_time=NOW()"),eq("good"));verify(j,never()).update(contains("DELETE"),any(Object[].class));}
}
